import{_ as t}from"./chunks/diagram_procesu1.Cry2C4TX.js";import{_ as e}from"./chunks/06.BRtrInto.js";import{_ as a}from"./chunks/01.DFo7dAfa.js";import{_ as r,o as n,c as s,aa as i}from"./chunks/framework.BAs_AphD.js";const g=JSON.parse('{"title":"Soupisy provedených prací","description":"","frontmatter":{"title":"Soupisy provedených prací","wiki":"cs:performedworks:start"},"headers":[],"relativePath":"performedworks/index.md","filePath":"performedworks/index.md","lastUpdated":1794209661000}'),l={name:"performedworks/index.md"};function d(p,o,v,h,u,k){return n(),s("div",null,[...o[0]||(o[0]=[i('<h1 id="soupisy-provedenych-praci" tabindex="-1">Soupisy provedených prací <a class="header-anchor" href="#soupisy-provedenych-praci" aria-label="Permalink to &quot;Soupisy provedených prací&quot;">​</a></h1><p>Modul <strong>Soupisy provedených prací</strong> slouží k měsíčnímu vykazování a schvalování prací provedených na stavbě. Zhotovitel u položek rozpočtu navrhne, co za období provedl, stavebník návrh po položkách schválí a schválený zjišťovací protokol je podkladem pro fakturu. Stejně to funguje mezi zhotovitelem a jeho podzhotoviteli.</p><p>Krok za krokem: <a href="/buildary-help-preview/akademie/jak-funguji-soupisy">Pochopit, jak fungují soupisy prací</a> a <a href="/buildary-help-preview/akademie/spp-podzhotovitele">Vést soupisy s podzhotoviteli</a> v Akademii.</p><h2 id="co-modul-umi" tabindex="-1">Co modul umí <a class="header-anchor" href="#co-modul-umi" aria-label="Permalink to &quot;Co modul umí&quot;">​</a></h2><ul><li>Na jedné stavbě pokryje soupisy mezi stavebníkem a zhotovitelem i mezi zhotovitelem a podzhotoviteli. Stavebníků, zhotovitelů i podzhotovitelů může být na stavbě libovolně mnoho.</li><li>Všichni pracují online nad stejnými daty, každý ale vidí jen soupisy své firmy a smí jen to, k čemu má kompetence.</li><li>Soupis se schvaluje po jednotlivých položkách. U každé položky zůstává vidět, jaké množství bylo navrženo, jak se návrh měnil a co bylo nakonec schváleno.</li><li>O změnách stavu protokolu posílá Buildary e-maily těm, kdo je mají v projektovém týmu zapnuté – viz <a href="/buildary-help-preview/performedworks/competences#e-mailova-oznameni">Kompetence pro soupisy</a>.</li><li>Výsledkem je zjišťovací protokol v PDF, elektronicky podepsaný proti změnám. V metadatech nese údaje, které využijete při příjmu faktury v ERP systému – viz <a href="/buildary-help-preview/performedworks/output_methods#podklad-k-fakturaci">Výstupy soupisů</a>.</li></ul><h2 id="zakladni-pojmy" tabindex="-1">Základní pojmy <a class="header-anchor" href="#zakladni-pojmy" aria-label="Permalink to &quot;Základní pojmy&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Pojem</th><th>Význam</th></tr></thead><tbody><tr><td><strong>Rozpočet</strong></td><td>Položkový rozpočet stavby. Každá položka má popis, měrnou jednotku, množství a jednotkovou cenu. Bez načteného rozpočtu soupisy zadávat nejde – viz <a href="/buildary-help-preview/performedworks/budget">Načíst rozpočet</a>.</td></tr><tr><td><strong>Období</strong></td><td>Časový úsek, za který se soupis zadává, obvykle kalendářní měsíc. Je společné pro celou stavbu – viz <a href="/buildary-help-preview/performedworks/period">Období soupisů</a>.</td></tr><tr><td><strong>Čerpání</strong></td><td>Množství a cena, které se u položky rozpočtu vykazují za období.</td></tr><tr><td><strong>Soupis provedených prací (soupis, SPP)</strong></td><td>Čerpání položek rozpočtu za období. V textu píšeme zkráceně soupis, zkratka SPP je v názvech oken a kompetencí.</td></tr><tr><td><strong>Zjišťovací protokol</strong></td><td>Soupis jedné dvojice firem (stavebník a zhotovitel, nebo zhotovitel a podzhotovitel) za jedno období. Protokol se odesílá na schválení, schvaluje a exportuje. Prochází stavy <strong>Návrh</strong>, <strong>Schvalování</strong>, <strong>Změna návrhu</strong> a <strong>Uzavřeno</strong> – viz <a href="/buildary-help-preview/performedworks/contractor_actions#stavy-zjistovaciho-protokolu">Zadat a schválit soupis</a>. Za stejné období tak na stavbě vzniká víc protokolů: jeden se stavebníkem a další s každým podzhotovitelem.</td></tr><tr><td><strong>Stav položky</strong></td><td>Rozhodnutí o jedné položce: <strong>Návrh</strong>, <strong>V jednání</strong>, <strong>Schváleno</strong>, <strong>Změna</strong> nebo <strong>Zamítnuto</strong> – viz <a href="/buildary-help-preview/performedworks/contractor_actions#stavy-polozky">Zadat a schválit soupis</a>.</td></tr></tbody></table><h2 id="jak-soupis-probiha" tabindex="-1">Jak soupis probíhá <a class="header-anchor" href="#jak-soupis-probiha" aria-label="Permalink to &quot;Jak soupis probíhá&quot;">​</a></h2><figure class="shot" style="--w:900px;"><img src="'+t+'" alt="Schéma procesu: administrátor stavby založí období, zástupce zhotovitele zadá návrh, zástupce stavebníka ho zkontroluje a buď vrátí k opravě, nebo odsouhlasí a uzamkne" loading="lazy"></figure><ol><li><strong>Administrátor stavby založí období.</strong> Uživatelé, kteří smějí soupisy zadávat, dostanou e-mail, že mohou začít.</li><li><strong>Zhotovitel zadá návrh.</strong> V okně <strong>SPP Zhotovitele</strong> vyplní u položek <strong>Navržené množství</strong>, cena se dopočítá. Hotový návrh odešle tlačítkem <strong>Odeslat na schválení</strong>. Protokol přejde do stavu <strong>Schvalování</strong> a stavebník dostane e-mail.</li><li><strong>Stavebník posoudí položky.</strong> Ve sloupci <strong>Stav položky</strong> každou položku schválí, změní její množství, zamítne ji, nebo ji nechá <strong>V jednání</strong>, pokud o ní chce se zhotovitelem ještě jednat. Může to dělat po jedné položce i hromadně a připomínky napsat do komentáře u položky.</li><li><strong>Stavebník protokol schválí, nebo vrátí.</strong><ul><li>Jsou-li všechny položky vyřešené, klikne na <strong>Schválit</strong>. Protokol se uzavře a uzamkne.</li><li>Zůstávají-li některé položky otevřené, klikne na <strong>Vrátit k opravě</strong>. Protokol přejde do stavu <strong>Změna návrhu</strong> a zhotovitel dostane e-mail.</li></ul></li><li><strong>Zhotovitel návrh opraví.</strong> U položek <strong>V jednání</strong> zadá nové množství ve sloupci <strong>Změna návrhu</strong> a protokol znovu odešle na schválení. Kroky 3 až 5 se opakují, dokud stavebník protokol neschválí.</li><li><strong>Zhotovitel vystaví fakturu.</strong> Po schválení mu přijde e-mail s elektronicky podepsaným zjišťovacím protokolem v PDF. Ten použije jako podklad k faktuře a přiloží ho k ní.</li></ol><figure class="shot" style="--w:760px;"><img src="'+e+'" alt="Okno SPP Zhotovitele ve stavu Schvalování se schválenými položkami a tlačítky Vrátit k opravě a Schválit" loading="lazy"></figure><p>Schválený protokol lze dodatečně upravit jen po odemknutí tlačítkem <strong>Odemknout</strong> – viz <a href="/buildary-help-preview/performedworks/contractor_actions#odemknout-schvaleny-protokol">Zadat a schválit soupis</a>. Podrobně o jednotlivých krocích: <a href="/buildary-help-preview/performedworks/application_window">Okno soupisu</a>, <a href="/buildary-help-preview/performedworks/contractor_actions">Zadat a schválit soupis</a> a <a href="/buildary-help-preview/performedworks/output_methods">Výstupy soupisů</a>.</p><h2 id="nez-zacnete" tabindex="-1">Než začnete <a class="header-anchor" href="#nez-zacnete" aria-label="Permalink to &quot;Než začnete&quot;">​</a></h2><ol><li>Zapněte na stavbě <strong>Modul Soupisy provedených prací</strong> – viz <a href="/buildary-help-preview/diary/projectsetup#pouzivane-moduly">Založit stavbu</a>.</li><li>Načtěte rozpočet – viz <a href="/buildary-help-preview/performedworks/budget">Načíst rozpočet</a>.</li><li>Přiřaďte lidi k firmám a dejte jim role s kompetencemi pro soupisy – viz <a href="/buildary-help-preview/performedworks/competences">Kompetence pro soupisy</a>.</li><li>Založte první období – viz <a href="/buildary-help-preview/performedworks/period">Období soupisů</a>.</li></ol><h2 id="kdo-co-dela" tabindex="-1">Kdo co dělá <a class="header-anchor" href="#kdo-co-dela" aria-label="Permalink to &quot;Kdo co dělá&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Krok</th><th>Kdo</th><th>Potřebná kompetence</th></tr></thead><tbody><tr><td>Založí období</td><td>administrátor stavby</td><td><strong>Administrace stavby</strong></td></tr><tr><td>Zadá navržené množství a odešle protokol na schválení</td><td>zhotovitel</td><td><strong>Zadání SPP zhotovitele</strong></td></tr><tr><td>Posoudí položky, protokol schválí nebo vrátí k opravě</td><td>stavebník</td><td><strong>Schvalování SPP zhotovitele</strong></td></tr><tr><td>Opraví položky <strong>V jednání</strong> a protokol odešle znovu</td><td>zhotovitel</td><td><strong>Zadání SPP zhotovitele</strong></td></tr></tbody></table><h2 id="u-podzhotovitelu-je-to-jinak" tabindex="-1">U podzhotovitelů je to jinak <a class="header-anchor" href="#u-podzhotovitelu-je-to-jinak" aria-label="Permalink to &quot;U podzhotovitelů je to jinak&quot;">​</a></h2><p>Soupisy mezi zhotovitelem a podzhotoviteli probíhají stejně jako mezi stavebníkem a zhotovitelem. Liší se v tom, co ukazuje tabulka:</p><table tabindex="0"><thead><tr><th></th><th>Soupis zhotovitele</th><th>Soupis podzhotovitele</th></tr></thead><tbody><tr><td>Okno</td><td><strong>SPP Zhotovitele</strong></td><td><strong>SPP Podzhotovitele</strong></td></tr><tr><td>Navrhuje</td><td>zhotovitel</td><td>podzhotovitel</td></tr><tr><td>Schvaluje</td><td>stavebník</td><td>zhotovitel</td></tr><tr><td>Volba v záhlaví okna</td><td><strong>Stavebník</strong> a <strong>Zhotovitel</strong></td><td><strong>Zhotovitel</strong> a <strong>Podzhotovitel</strong></td></tr><tr><td>Kompetence</td><td><strong>Zadání SPP zhotovitele</strong>, <strong>Schvalování SPP zhotovitele</strong></td><td><strong>Zadání SPP podzhotovitele</strong>, <strong>Schvalování SPP podzhotovitele</strong></td></tr><tr><td>Položky</td><td>položky rozpočtu</td><td>jen položky, které mají v rozpočtu vyplněnou kalkulační část s podzhotovitelem – viz <a href="/buildary-help-preview/performedworks/budget">Načíst rozpočet</a></td></tr><tr><td>PDF po schválení dostane</td><td>zhotovitel</td><td>podzhotovitel</td></tr></tbody></table><figure class="shot" style="--w:760px;"><img src="'+a+'" alt="Okno SPP Podzhotovitele s volbou zhotovitele a podzhotovitele a položkami rozpočtu" loading="lazy"></figure><ul><li>Podzhotovitelů bývá na stavbě víc, takže zhotovitel za jedno období vede a schvaluje víc zjišťovacích protokolů najednou – s každým podzhotovitelem jeden.</li><li>Období je společné: období založené pro soupisy zhotovitele platí i pro podzhotovitele.</li><li>Zadávat soupis za podzhotovitele může i někdo ze zhotovitele, například stavbyvedoucí. Potřebuje být přiřazený i k firmě podzhotovitele a mít kompetenci <strong>Zadání SPP podzhotovitele</strong> – viz <a href="/buildary-help-preview/performedworks/competences">Kompetence pro soupisy</a>.</li></ul>',21)])])}const y=r(l,[["render",d]]);export{g as __pageData,y as default};
